  // Where it comes from + how the installer fetches it. One of: modrinth, curseforge,
  // hangar, spigotmc, steam_workshop, thunderstore, umod, codefling, nexus, ficsit,
  // rocketmod, factorio_portal, mcpedl, github, mod_io, vintagestory_moddb,
  // reforger_workshop, manual. (Comment only — source is a plain String.)
  source           String
  sourceId         String? // workshop id / curseforge project id / modrinth slug / etc.
  url              String?
  modStringId      String? // e.g. Project Zomboid's Mods= string id (distinct from the numeric Workshop id)
  appliesToVariant String? // restrict to a loader/variant (e.g. "paper", "oxide", "carbon"); null = any
  description      String?
  iconUrl          String?
  popularity       Int         @default(0) // higher = more popular (sort key)
  paid             Boolean     @default(false)
  featured         Boolean     @default(false)
  active           Boolean     @default(true)
  createdAt        DateTime    @default(now())
  updatedAt        DateTime    @updatedAt
  installs         ServerMod[]

  // ── Verified upstream facts (scripts/verify-gamemods.ts) ─────────────────
  // Everything below is READ FROM THE SOURCE API, never hand-written: the
  // storefront's previous star ratings and install counts were computed from a
  // hash of the slug, and the fix is not better guesses but real numbers.
  /// Game versions the source says this supports. Empty = the source has no
  /// version list (uMod, Steam Workshop), which is not the same as "none".
  gameVersions    String[]  @default([])
  /// Loaders/platforms the source lists (paper, spigot, fabric, forge, …).
  loaders         String[]  @default([])
  /// Real download count from the source. Null where the source exposes none.
  downloads       Int?
  /// Primary file size in bytes — the objective half of the impact rating.
  fileBytes       Int?
  /// How many other projects the latest build requires.
  dependencyCount Int       @default(0)
  /// "required" | "optional" | "unsupported" — a client-only mod cannot be
  /// installed on a server at all, and the catalogue should not offer it.
  serverSide      String?
  /// Resource weight shown as a warning: light | moderate | heavy.
  impact          String    @default("light")
  /// Why this one is heavy, in the customer's words, on its own card.
  impactNote      String?
  /// When the fields above were last confirmed against the source.
  verifiedAt      DateTime?
  /// False once a verification pass fails to find the project upstream — a
  /// dead entry must stop being offered rather than 404 at install time.
model ServerMod {
  id          String   @id @default(cuid())
  serverId    String
  server      Server   @relation(fields: [serverId], references: [id], onDelete: Cascade)
  modId       String
  mod         GameMod  @relation(fields: [modId], references: [id])
  status      String   @default("INSTALLING") // INSTALLING | INSTALLED | FAILED | REMOVING | REMOVED
  version     String?
  error       String? // last failure detail, surfaced in the portal
  installedAt DateTime @default(now())
  updatedAt   DateTime @updatedAt

  // ── Mod auto-update (lib/mod-autoupdate/*, 2026-10-01; ALL additive) ──────
  /// Provider version id of what is installed now (Modrinth version id,
  /// Thunderstore version number, Hangar version name). Copied from the guest
  /// state file (/root/.nxeon-mods/state.json) after every check/apply.
  versionId          String?
  /// Primary file the engine placed for this mod (basename) + its sha256.
  fileName           String?
  fileSha256         String?
  /// Owner pinned this version: never auto-updated, never offered as an update.
  pinned             Boolean   @default(false)
  /// Per-mod override: OFF | NOTIFY | AUTO. Null = inherit the server default
  /// (ModAutoUpdateSettings.mode), subject to the clientRequired gate.
  autoUpdate         String?
  /// Players must have the SAME version on their own game (Valheim gameplay
  /// mods, Fabric/Forge mods with client_side=required). Null = unknown.
  clientRequired     Boolean?
  /// Why clientRequired is what it is ("Modrinth: client_side=required").
  clientReason       String?
  /// Newest COMPATIBLE version the last check found (null = none newer).
  availableVersion   String?
  availableVersionId String?
  /// The resolver's human-readable decision for this mod at the last check.
  availableReason    String?   @db.Text
  lastCheckAt        DateTime?
  lastUpdateAt       DateTime?
  /// Consecutive failed auto-updates (reset on success); 3 → paused.
  updateFailures     Int       @default(0)
  lastFailure        String?   @db.Text
  /// Cyrus mods (2026-10-07, additive): the EXACT provider version the next
  /// INSTALLING/UPDATING run must place (a Cyrus build id, for "update to
  /// latest" and rollback). Null = the resolver's own choice. Cleared after the run.
  targetVersionId    String?

  @@unique([serverId, modId])
  @@index([serverId])
}

