// Cyrus mods <-> the mods engine: the GameMod row that stands for a Cyrus mod,
// and the jar source the engine's "cyrus" resolver reads from.
// Plain module (no next/* imports): the worker imports it too.
import { flightBlocks } from "../cyrus/testflight/gate";
import type { GameMod, ModBuild } from "@prisma/client";
import { readFile } from "node:fs/promises";
import { db } from "../db";
import { cyrusDb } from "../cyrus/db";
import { CYRUS_SOURCE, type CyrusJar } from "../mods/installers/cyrus";
import { currentVersion, displayName, mayInstallChain, packageVersionFor, succeededVersions, readModDoc } from "./doc";
export { packageVersionFor } from "./doc";

export const cyrusModSlug = (rootBuildId: string) => `cyrus-${rootBuildId}`.toLowerCase().replace(/[^a-z0-9-]/g, "-").slice(0, 80);

/** Every build of a chain (root + its versions), oldest first. */
export async function loadChain(rootBuildId: string): Promise<ModBuild[]> {
  return cyrusDb.modBuild.findMany({ where: { OR: [{ id: rootBuildId }, { rootBuildId }] }, orderBy: { createdAt: "asc" } });
}

/** The chain root of a build (self for v1 / old rows without rootBuildId). */
export const rootOf = (b: Pick<ModBuild, "id" | "rootBuildId">) => b.rootBuildId ?? b.id;

/**
 * The GameMod row the mods engine knows this Cyrus mod by (created on first
 * install, refreshed after every new version). Never listed in the catalogue:
 * active=false, and every catalogue query filters active=true.
 */
export async function ensureCyrusGameMod(rootBuildId: string, chain?: ModBuild[]): Promise<GameMod | null> {
  const builds = chain ?? (await loadChain(rootBuildId));
  const cur = currentVersion(builds);
  if (!cur) return null;
  const page = await cyrusDb.cyrusModPage.findUnique({ where: { rootBuildId } }).catch(() => null);
  const doc = page ? readModDoc(page.doc) : null;
  const name = displayName(builds);
  const owner = await db.user.findUnique({ where: { id: builds[0].userId }, select: { name: true } }).catch(() => null);
  const data = {
    name,
    category: "Plugins",
    description: doc?.tagline ?? null,
    loaders: ["paper", "purpur"],
    gameVersions: [...new Set(succeededVersions(builds).map((b) => b.mcVersion))],
    serverSide: "required",
    fileBytes: cur.jarSize ?? null,
    license: page?.license ?? "MIT",
    authorName: owner?.name ?? null,
    url: page ? `/dashboard/nxlabs/cyrus/${page.slug}` : null,
  };
  return db.gameMod.upsert({
    where: { gameFamily_slug: { gameFamily: "minecraft", slug: cyrusModSlug(rootBuildId) } },
    create: { gameFamily: "minecraft", slug: cyrusModSlug(rootBuildId), source: CYRUS_SOURCE, sourceId: rootBuildId, active: false, impact: "light", ...data },
    update: data,
  });
}

/** Engine jar source: the build to place, checked against the server's owner. */
export async function loadCyrusJar(args: { rootBuildId: string; targetBuildId: string | null; serverId: string }): Promise<CyrusJar | { error: string }> {
  const [chain, server] = await Promise.all([
    loadChain(args.rootBuildId),
    db.server.findUnique({ where: { id: args.serverId }, select: { userId: true } }),
  ]);
  if (!chain.length || !server) return { error: "This Cyrus mod's build history wasn't found." };
  // Owner check: the creator's own servers take any of their builds. Cyrus v6 community: anyone's
  // server may take a PUBLISHED mod (the same jar its public page already offers for download);
  // a private or hidden page stays the creator's only (lib/cyrus-mods/doc.ts mayInstallChain).
  if (chain[0].userId !== server.userId) {
    const page = await cyrusDb.cyrusModPage.findUnique({ where: { rootBuildId: args.rootBuildId }, select: { visibility: true, hiddenAt: true } }).catch(() => null);
    if (!mayInstallChain({ chainOwnerId: chain[0].userId, serverOwnerId: server.userId, page })) return { error: "This Cyrus mod belongs to another account and isn't published." };
  }
  const ok = succeededVersions(chain);
  const build = args.targetBuildId ? ok.find((b) => b.id === args.targetBuildId) : currentVersion(chain);
  if (!build) return { error: args.targetBuildId ? "That version isn't a finished build of this mod." : "This Cyrus mod has no finished version yet." };
  // Owner check: the creator's own servers take any of their builds (forks are the forker's own
  // copies). Another account's server only takes PUBLISHED versions of a public page (installed
  // from NxLabs, Cyrus lifecycle 2026-10-08), re-checked on every install/update.
  if (chain[0].userId !== server.userId) {
    const { publicInstallAllowed } = await import("../cyrus/lifecycle/server");
    if (!(await publicInstallAllowed(build, server.userId))) return { error: "This Cyrus mod belongs to another account and isn't published, so it can't be installed or updated." };
  }
  // Cyrus R5: optional gate (CYRUS_TESTFLIGHT_BLOCK_ON_FAIL=1): a version whose Test Flight FAILED is not installed.
  const fb = flightBlocks((build.cyrus as { testFlight?: unknown } | null)?.testFlight);
  if (fb.blocked) return { error: fb.reason };
  if (!build.jarPath || !build.jarName) return { error: "That version has no plugin file." };
  let bytes: Buffer;
  try {
    bytes = await readFile(build.jarPath);
  } catch {
    return { error: "The plugin file for that version is missing from storage. Rebuild it in Cyrus." };
  }
  return {
    build: { id: build.id, version: build.version, pluginName: build.pluginName, jarName: build.jarName, jarSha256: build.jarSha256, mcVersion: build.mcVersion },
    name: displayName(chain),
    packageVersion: packageVersionFor(build, chain),
    bytes,
  };
}

