/**
 * Admin controls for NX Labs catalog ingestion (/admin/nxlabs). These only flip
 * flags on the ModSyncProvider row; the worker (worker/modsync.ts) does the
 * actual crawling, so the web app never makes upstream calls itself.
 */
type Result = { error?: string; ok?: boolean };
type Action = "pause" | "resume" | "run-now" | "reset-cursor" | "enable" | "disable";

export async function adminModsyncControl(key: string, action: Action): Promise<Result> {
  const admin = await requireArea("billing");
  if (!providerByKey(key)) return { error: "Unknown provider." };
  const row = await db.modSyncProvider.findUnique({ where: { key } });
  if (!row) return { error: "Provider has not been initialised by the worker yet." };
  switch (action) {
    case "pause": await db.modSyncProvider.update({ where: { key }, data: { paused: true } }); break;
    case "resume": await db.modSyncProvider.update({ where: { key }, data: { paused: false, nextRunAt: new Date() } }); break;
    case "enable": await db.modSyncProvider.update({ where: { key }, data: { enabled: true, nextRunAt: new Date() } }); break;
    case "disable": await db.modSyncProvider.update({ where: { key }, data: { enabled: false } }); break;
    case "run-now": await db.modSyncProvider.update({ where: { key }, data: { runRequested: true, paused: false, enabled: true, nextRunAt: new Date() } }); break;
    case "reset-cursor": await db.modSyncProvider.update({ where: { key }, data: { cursor: Prisma.JsonNull, lastStats: Prisma.JsonNull } }); break;
    default: return { error: "Unknown action." };
  }
  await recordAudit(admin.id, "modsync.control", `${key} → ${action}`);
  revalidatePath("/admin/nxlabs");
  return { ok: true };
}

// The ONE door to Cyrus' own database. Cyrus code imports `cyrusDb` from here (never lib/db). It resolves through the host
// registry on every use, so setHost() (tests, a standalone deployment) takes effect immediately. Typed as CyrusDb: only
// Cyrus' own tables plus $transaction/raw SQL exist on it; platform tables must go through the host's methods.
import { getHost } from "./host";
import type { CyrusDb } from "./host";

export type { CyrusDb };
export const cyrusDb: CyrusDb = new Proxy({} as CyrusDb, {
  get(_t, prop) {
    const c = getHost().db as unknown as Record<PropertyKey, unknown>;
    const v = c[prop];
    return typeof v === "function" ? (v as (...a: unknown[]) => unknown).bind(c) : v;
  },
  set(_t, prop, value) { (getHost().db as unknown as Record<PropertyKey, unknown>)[prop] = value; return true; },
  has(_t, prop) { return prop in (getHost().db as object); },
});
// Cyrus mod pages: the SERVER half. Generates/refreshes CyrusModPage rows from
// ModBuild chains (pure generator in ./doc.ts) and reads them for viewers.
// Plain module: called from lib/modbuilder/store.ts (API routes + worker sweep).
import type { CyrusModPage, ModBuild, Prisma } from "@prisma/client";
import { db } from "../db";
import { cyrusDb } from "../cyrus/db";
import { buildModDoc, pageVisibleTo, readModDoc, slugifyModName, uniqueSlug, type CyrusModDoc } from "./doc";
import { ensureCyrusGameMod, loadChain, rootOf } from "./registry";

/**
 * Create (first successful version) or refresh (every later version) the page
 * for a build's chain. Private by default. Never throws for the caller: a page
 * failure must not fail a build.
 */
export async function syncCyrusModPage(rootBuildId: string): Promise<CyrusModPage | null> {
  try {
    const chain = await loadChain(rootBuildId);
    if (!chain.length) return null;
    const doc = buildModDoc(chain);
    if (!doc) return null;
    const existing = await cyrusDb.cyrusModPage.findUnique({ where: { rootBuildId } });
    // Cyrus v6: a creator's own short description (NxLabs listing) wins over the generated one.
    const custom = existing ? await cyrusDb.cyrusModListing.findUnique({ where: { pageId: existing.id }, select: { tagline: true } }).catch(() => null) : null;
    const data = {
      title: doc.name.slice(0, 80),
      tagline: custom?.tagline || doc.tagline,
      latestBuildId: doc.currentBuildId,
      latestVersion: doc.versions.find((v) => v.buildId === doc.currentBuildId)?.version ?? null,
      doc: doc as unknown as Prisma.InputJsonValue,
    };
    let page: CyrusModPage;
    if (existing) {
      page = await cyrusDb.cyrusModPage.update({ where: { id: existing.id }, data });
    } else {
      const base = slugifyModName(doc.name);
      const taken = new Set((await cyrusDb.cyrusModPage.findMany({ where: { slug: { startsWith: base.slice(0, 40) } }, select: { slug: true } })).map((r) => r.slug));
      const fork = await cyrusDb.cyrusFork.findUnique({ where: { buildId: rootBuildId } }).catch(() => null);
      try {
        page = await cyrusDb.cyrusModPage.create({
          data: { rootBuildId, userId: chain[0].userId, slug: uniqueSlug(base, taken), ...data, ...(fork ? { forkOfPageId: fork.sourcePageId, forkOfBuildId: fork.sourceBuildId } : {}) },
        });
      } catch {
        // Two syncs raced (sweep + an open page): the other one created it.
        const again = await cyrusDb.cyrusModPage.findUnique({ where: { rootBuildId } });
        if (!again) return null;
        page = await cyrusDb.cyrusModPage.update({ where: { id: again.id }, data });
      }
    }
    // Keep the engine's GameMod (name/size/versions) in step when the mod has one.
    const gm = await db.gameMod.findFirst({ where: { source: "cyrus", sourceId: rootBuildId }, select: { id: true } });
    if (gm) await ensureCyrusGameMod(rootBuildId, chain).catch(() => null);
    return page;
  } catch (e) {
    console.error("[cyrus-mods] page sync failed", rootBuildId, (e as Error).message);
    return null;
  }
}

/** Hook for a build row that just changed (store.ts). Only a success creates/refreshes a page. */
export async function onBuildSettled(row: Pick<ModBuild, "id" | "rootBuildId" | "status">): Promise<void> {
  if (row.status !== "succeeded") return;
  const page = await syncCyrusModPage(rootOf(row));
  // r38: mod.published webhook for a public page (no-op unless CYRUS_API_V1_WEBHOOKS)
  if (page) await (await import("../cyrus/api/v1/emit")).emitModPublished({ userId: page.userId, slug: page.slug, buildId: row.id, version: null, visibility: page.visibility, publishedAt: page.publishedAt });
}

export type PageView = {
  id: string;
  slug: string;
  title: string;
  tagline: string | null;
  visibility: "PRIVATE" | "PUBLIC";
  license: string;
  hidden: boolean;
  hiddenReason: string | null;
  publishedAt: string | null;
  updatedAt: string;
  createdAt: string;
  creator: { id: string; name: string };
  isCreator: boolean;
  isAdmin: boolean;
  rootBuildId: string;
  doc: CyrusModDoc;
  forkOf: { slug: string; title: string } | null;
  forks: number;
  threads: { open: number; bugsOpen: number; total: number };
};

/** Public credit: the account's display name only — never any part of the email. */
export const displayUser = (u: { name: string | null } | null) => (u?.name?.trim() || "Nxeon customer").slice(0, 40);

export async function toPageView(page: CyrusModPage, viewer: { id: string; role?: string | null } | null): Promise<PageView | null> {
  const doc = readModDoc(page.doc);
  if (!doc) return null;
  const [creator, forkOf, forks, open, bugsOpen, total] = await Promise.all([
    db.user.findUnique({ where: { id: page.userId }, select: { name: true } }),
    page.forkOfPageId ? cyrusDb.cyrusModPage.findUnique({ where: { id: page.forkOfPageId }, select: { slug: true, title: true, visibility: true, hiddenAt: true, userId: true } }) : null,
    cyrusDb.cyrusFork.count({ where: { sourcePageId: page.id } }),
    cyrusDb.cyrusModPost.count({ where: { pageId: page.id, parentId: null, status: "OPEN", hiddenAt: null } }),
    cyrusDb.cyrusModPost.count({ where: { pageId: page.id, parentId: null, status: "OPEN", kind: "BUG", hiddenAt: null } }),
    cyrusDb.cyrusModPost.count({ where: { pageId: page.id, parentId: null, hiddenAt: null } }),
  ]);
  return {
    id: page.id,
    slug: page.slug,
    title: page.title,
    tagline: page.tagline,
    visibility: page.visibility === "PUBLIC" ? "PUBLIC" : "PRIVATE",
    license: page.license,
    hidden: !!page.hiddenAt,
    hiddenReason: page.hiddenReason,
    publishedAt: page.publishedAt?.toISOString() ?? null,
    updatedAt: page.updatedAt.toISOString(),
    createdAt: page.createdAt.toISOString(),
    creator: { id: page.userId, name: displayUser(creator) },
    isCreator: !!viewer && viewer.id === page.userId,
    isAdmin: viewer?.role === "ADMIN",
    rootBuildId: page.rootBuildId,
    doc,
    // A fork's parent is only named when the viewer may see it.
    forkOf: forkOf && pageVisibleTo(forkOf, viewer) ? { slug: forkOf.slug, title: forkOf.title } : null,
    forks,
    threads: { open, bugsOpen, total },
  };
}

/** A page by slug, or null when it doesn't exist or this viewer may not see it. */
export async function pageForViewer(slug: string, viewer: { id: string; role?: string | null } | null): Promise<PageView | null> {
  if (!/^[a-z0-9-]{3,60}$/.test(slug)) return null;
  const page = await cyrusDb.cyrusModPage.findUnique({ where: { slug } });
  if (!page || !pageVisibleTo(page, viewer)) return null;
  return toPageView(page, viewer);
}

export type PageCard = {
  slug: string; title: string; tagline: string | null; creator: string; version: string | null; versions: number; mcVersions: string[]; commands: number; updatedAt: string; visibility: string; mine: boolean; bugsOpen: number;
  /** Cyrus v6 community (lib/cyrus-mods/social.ts): the creator's icon, real star / installer counts, the computed Community-tested status, remix credit. */
  iconUrl?: string | null; stars?: number; installers?: number; tested?: boolean; remixOf?: string | null; category?: string | null; tags?: string[];
};

/** The NxLabs "Cyrus Mods" listing: public pages, plus the viewer's own (private included). */
export async function listPageCards(viewer: { id: string } | null, opts: { q?: string; mineOnly?: boolean; take?: number } = {}): Promise<PageCard[]> {
  const q = (opts.q ?? "").trim().slice(0, 60);
  const visible: Prisma.CyrusModPageWhereInput = opts.mineOnly && viewer
    ? { userId: viewer.id }
    : { OR: [{ visibility: "PUBLIC", hiddenAt: null }, ...(viewer ? [{ userId: viewer.id }] : [])] };
  // Cyrus v6: a search also matches a creator's tags (lib/cyrus-mods/listing.ts normaliseTag).
  const tagged = q ? (await cyrusDb.cyrusModListing.findMany({ where: { tags: { has: q.toLowerCase().replace(/^#/, "") } }, select: { pageId: true }, take: 200 }).catch(() => [])).map((l) => l.pageId) : [];
  const where: Prisma.CyrusModPageWhereInput = q ? { AND: [visible, { OR: [{ title: { contains: q, mode: "insensitive" } }, { tagline: { contains: q, mode: "insensitive" } }, ...(tagged.length ? [{ id: { in: tagged } }] : [])] }] } : visible;
  const rows = await cyrusDb.cyrusModPage.findMany({ where, orderBy: { updatedAt: "desc" }, take: Math.min(60, opts.take ?? 24) });
  const users = await db.user.findMany({ where: { id: { in: [...new Set(rows.map((r) => r.userId))] } }, select: { id: true, name: true } });
  const bugs = rows.length ? await cyrusDb.cyrusModPost.groupBy({ by: ["pageId"], where: { pageId: { in: rows.map((r) => r.id) }, parentId: null, kind: "BUG", status: "OPEN", hiddenAt: null }, _count: { _all: true } }) : [];
  const { statsFor, listingsFor, toListingView, testedFor } = await import("./social");
  const [stats, { listings, media }] = await Promise.all([statsFor(rows).catch(() => new Map()), listingsFor(rows.map((r) => r.id)).catch(() => ({ listings: new Map(), media: new Map() }))]);
  const parents = new Map((await cyrusDb.cyrusModPage.findMany({ where: { id: { in: [...new Set(rows.map((r) => r.forkOfPageId).filter((x): x is string => !!x))] } }, select: { id: true, title: true, visibility: true, hiddenAt: true, userId: true } })).map((p) => [p.id, p]));
  return rows.flatMap((r) => {
    const d = readModDoc(r.doc);
    if (!d) return [];
    const st = stats.get(r.id);
    const lv = toListingView(listings.get(r.id) ?? null, media.get(r.id) ?? [], !!viewer && viewer.id === r.userId);
    const parent = r.forkOfPageId ? parents.get(r.forkOfPageId) : undefined;
    return [{
      iconUrl: lv.icon?.url ?? null,
      stars: st?.stars ?? 0,
      installers: st?.installers ?? 0,
      tested: st ? testedFor(r, d, st).earned : false,
      remixOf: parent && pageVisibleTo(parent, viewer) ? parent.title : null,
      category: lv.category,
      tags: lv.tags,
      slug: r.slug,
      title: r.title,
      tagline: r.tagline,
      creator: displayUser(users.find((u) => u.id === r.userId) ?? null),
      version: r.latestVersion,
      versions: d.versions.length,
      mcVersions: d.compat.mcVersions,
      commands: d.commands.length,
      updatedAt: r.updatedAt.toISOString(),
      visibility: r.visibility,
      mine: !!viewer && r.userId === viewer.id,
      bugsOpen: bugs.find((b) => b.pageId === r.id)?._count._all ?? 0,
    }];
  });
}

/** Self-heal: make sure every finished chain the user owns has a page (old builds predate this). */
export async function backfillUserPages(userId: string): Promise<number> {
  const roots = await cyrusDb.modBuild.findMany({ where: { userId, status: "succeeded" }, select: { id: true, rootBuildId: true }, take: 200 });
  const ids = [...new Set(roots.map((r) => r.rootBuildId ?? r.id))];
  const have = new Set((await cyrusDb.cyrusModPage.findMany({ where: { rootBuildId: { in: ids } }, select: { rootBuildId: true } })).map((p) => p.rootBuildId));
  let n = 0;
  for (const id of ids) if (!have.has(id) && (await syncCyrusModPage(id))) n++;
  return n;
}

/** Public slugs for the sitemap (only used when launched). */
export async function publicPageSlugs(): Promise<{ slug: string; updatedAt: Date }[]> {
  return cyrusDb.cyrusModPage.findMany({ where: { visibility: "PUBLIC", hiddenAt: null }, select: { slug: true, updatedAt: true }, orderBy: { updatedAt: "desc" }, take: 5000 });
}

