235	export async function setCyrusPageVisibility(slug: string, visibility: "PUBLIC" | "PRIVATE"): Promise<{ ok?: true; error?: string }> {
236	  const { user, allowed } = await requireViewer();
237	  if (!allowed || !user) return NF;
238	  const page = await pageFor(slug, user);
239	  if (!page) return NF;
240	  if (page.userId !== user.id) return { error: "Only the mod's creator can publish it." };
241	  if (visibility !== "PUBLIC" && visibility !== "PRIVATE") return { error: "Bad visibility." };
242	  if (visibility === "PUBLIC" && (await cyrusSuspension(user.id, "community"))) return { error: SUSPENDED };
243	  if (visibility === "PUBLIC" && process.env.CYRUS_TESTFLIGHT_BLOCK_ON_FAIL === "1") {
244	    // Cyrus R5 optional gate: the current version's Test Flight must not have FAILED ("not run" never blocks)
245	    const chain = await loadChain(page.rootBuildId);
246	    const head = currentVersion(chain);
247	    const fb = flightBlocks((head?.cyrus as { testFlight?: unknown } | null | undefined)?.testFlight);
248	    if (fb.blocked) return { error: fb.reason };
249	  }
250	  await cyrusDb.cyrusModPage.update({ where: { id: page.id }, data: { visibility, ...(visibility === "PUBLIC" && !page.publishedAt ? { publishedAt: new Date() } : {}) } });
251	  await db.auditLog.create({ data: { userId: user.id, action: "cyrusmods.visibility", detail: `${page.slug} ${visibility}` } }).catch(() => {});
252	  revalidate(page.slug);
253	  revalidatePath("/dashboard/nxlabs/cyrus");
254	  return { ok: true };
255	}
