296	  const reason = str(fd, "reason", 200) || "Hidden by Nxeon after review";
297	  await cyrusDb.cyrusModPost.update({ where: { id: postId }, data: hide ? { hiddenAt: post.hiddenAt ?? new Date(), hiddenById: admin.id, hiddenReason: reason } : { hiddenAt: null, hiddenById: null, hiddenReason: null, reportCount: 0 } });
298	  await cyrusAudit({ actorId: admin.id, action: hide ? "report.hide" : "report.dismiss", target: `post:${postId}`, before: { hidden: !!post.hiddenAt, hiddenReason: post.hiddenReason, openReports: open, reportCount: post.reportCount }, after: { hidden: hide, hiddenReason: hide ? reason : null, openReports: 0 } });
