323	  await cyrusAudit({ actorId: admin.id, action: down ? "page.takedown" : "page.restore", target: `page:${page.slug}`, before: { hidden: !!page.hiddenAt, reason: page.hiddenReason }, after: { hidden: down, reason: down ? reason : null } });
324	  go(fd, "ok", down ? `“${page.title}” taken down.` : `“${page.title}” restored.`);
