327	/** Feature or unfeature a PUBLIC, not-taken-down mod page on the marketing surfaces (/mods/cyrus and the cyrus.my landing). */
328	export async function adminCyrusFeatureListing(fd: FormData) {
329	  const on = fd.get("on") === "1";
330	  const admin = await guard("mods.feature");
331	  const pageId = str(fd, "pageId", 40);
332	  const page = await cyrusDb.cyrusModPage.findUnique({ where: { id: pageId }, select: { id: true, slug: true, title: true, visibility: true, hiddenAt: true, doc: true } });
333	  if (!page) go(fd, "err", "No such mod page.");
334	  if (on) {
335	    const { readModDoc } = await import("./cyrus/mods/doc");
336	    const { flightFailedVerdict } = await import("./cyrus/app/failure");
337	    if (flightFailedVerdict(readModDoc(page.doc)?.testFlight)) go(fd, "err", "This mod did not load in the test server (its Test Flight failed). It cannot be featured until a new version passes.");
338	  }
339	  if (on && !(page.visibility === "PUBLIC" && !page.hiddenAt)) go(fd, "err", "Only public mods that are not taken down can be featured.");
340	  const { FEATURED_KEY, parseFeatured, setFeatured } = await import("./cyrus-mods/featured");
341	  const before = parseFeatured(await settingValue(FEATURED_KEY));
342	  const next = setFeatured(before, pageId, on);
343	  if (!next.ok) go(fd, "err", next.error);
344	  if (next.list.join() === before.join()) go(fd, "ok", "No change.");
345	  await setOrClear(FEATURED_KEY, next.list.length ? JSON.stringify(next.list) : null);
346	  await cyrusAudit({ actorId: admin.id, action: "mods.feature", target: `page:${page.slug}`, before: { featured: before.includes(pageId) }, after: { featured: on, position: on ? next.list.indexOf(pageId) + 1 : null } });
347	  go(fd, "ok", on ? `“${page.title}” is featured.` : `“${page.title}” is no longer featured.`);
348	}
