// Cyrus notifications (r40): the ONE event catalogue + the preference model. PURE, client-safe.
// Unit-tested in test/cyrus-admin-r40.test.ts. Server side: ./index.ts (store + send), ./templates.ts (email).

export type NotifyEvent = "build.finished" | "install.result" | "mod.outdated" | "takedown" | "tokens.low";
export type Channel = "inApp" | "email";
export type EventDef = { id: NotifyEvent; label: string; what: string; defaults: Record<Channel, boolean>; /** email cannot be turned off */ required?: Channel[] };

export const NOTIFY_EVENTS: EventDef[] = [
  { id: "build.finished", label: "Build finished", what: "A build or change you started succeeded or failed.", defaults: { inApp: true, email: false } },
  { id: "install.result", label: "Install result", what: "A mod, data pack or Mod Pack was installed on (or rolled back from) one of your servers.", defaults: { inApp: true, email: true } },
  { id: "mod.outdated", label: "Mod outdated", what: "A game or loader update means one of your mods probably needs a rebuild.", defaults: { inApp: true, email: true } },
  { id: "takedown", label: "Takedown", what: "Something you published, or an asset your project uses, was taken down. Always emailed: it can need your reply.", defaults: { inApp: true, email: true }, required: ["inApp", "email"] },
  { id: "tokens.low", label: "Low tokens", what: "Your Cyrus token balance fell below the low-balance mark.", defaults: { inApp: true, email: false } },
];

export const isNotifyEvent = (v: unknown): v is NotifyEvent => typeof v === "string" && NOTIFY_EVENTS.some((e) => e.id === v);
export const eventDef = (id: NotifyEvent) => NOTIFY_EVENTS.find((e) => e.id === id)!;

export type Prefs = Partial<Record<NotifyEvent, Partial<Record<Channel, boolean>>>>;

/** Tolerant parse of the stored JSON (unknown events / non-booleans dropped). */
export function parsePrefs(v: unknown): Prefs {
  if (!v || typeof v !== "object" || Array.isArray(v)) return {};
  const out: Prefs = {};
  for (const e of NOTIFY_EVENTS) {
    const x = (v as Record<string, unknown>)[e.id];
    if (!x || typeof x !== "object") continue;
    const c: Partial<Record<Channel, boolean>> = {};
    for (const ch of ["inApp", "email"] as Channel[]) { const b = (x as Record<string, unknown>)[ch]; if (typeof b === "boolean") c[ch] = b; }
    if (Object.keys(c).length) out[e.id] = c;
  }
  return out;
}

/** Is this channel on for this event? Required channels are always on. */
export function wants(p: Prefs, ev: NotifyEvent, ch: Channel): boolean {
  const d = eventDef(ev);
  if (d.required?.includes(ch)) return true;
  return p[ev]?.[ch] ?? d.defaults[ch];
}

/** The preference center form -> stored prefs (only differences from the defaults are kept). */
export function prefsFromForm(get: (k: string) => string | null): Prefs {
  const out: Prefs = {};
  for (const e of NOTIFY_EVENTS) {
    for (const ch of ["inApp", "email"] as Channel[]) {
      if (e.required?.includes(ch)) continue;
      const on = get(`${e.id}:${ch}`) === "1" || get(`${e.id}:${ch}`) === "on";
      if (on !== e.defaults[ch]) (out[e.id] ??= {})[ch] = on;
    }
  }
  return out;
}

/** Dedupe key per event: one notification per (user, event, ref). */
export function refFor(ev: NotifyEvent, data: Record<string, unknown>): string {
  const pick = (k: string) => String(data[k] ?? "").slice(0, 120);
  switch (ev) {
    case "build.finished": return `${pick("buildId")}:${pick("status")}`;
    case "install.result": return `${pick("jobId") || pick("installId")}:${pick("ok")}`;
    case "mod.outdated": return `${pick("modId")}:${pick("version")}`;
    // r49 (re-audit C-M2): one notice per takedown ACTION, so a second takedown of the same target (after a restore,
    // or in a later legal case) is not swallowed as a duplicate; `at` is fixed once per action by notifyTakedown
    case "takedown": return data.at ? `${pick("target")}:${pick("at")}` : `${pick("target")}`;
    case "tokens.low": return new Date(Number(data.at) || Date.now()).toISOString().slice(0, 10); // at most once a day
  }
}

export const NOTIFY_FLAG = "CYRUS_NOTIFY";
export const NOTIFY_EMAIL_FLAG = "CYRUS_NOTIFY_EMAIL";
export const MAIL_FROM_SETTING = "cyrus_mail_from";
export const notifyEnabled = (env: Record<string, string | undefined> = process.env) => env[NOTIFY_FLAG] === "1";
export const notifyEmailEnabled = (env: Record<string, string | undefined> = process.env) => notifyEnabled(env) && env[NOTIFY_EMAIL_FLAG] === "1";
/** A sender is only valid on the cyrus.my domain (SPF/DKIM/DMARC for it: docs "Cyrus email sender"). */
export const validCyrusSender = (from: string) => /^(?:[^<>@\r\n]{1,60} )?<?[a-z0-9._+-]{1,64}@cyrus\.my>?$/i.test(from.trim());
// Cyrus notification hooks (r40): small adapters the product code calls at the moment something happens. Each one is
// fire-and-forget and off unless CYRUS_NOTIFY=1 (lib/cyrus/notify/index.ts). HOST SEAM: Cyrus modules only.
import { notifyEnabled } from "./events";
import { notify } from "./index";

/** A build reached succeeded/failed: tell the person, then check whether the settle left them low on tokens. */
export function notifyBuildFinished(b: { id: string; userId: string; status: string; pluginName: string | null; errorCode: string | null }): void {
  if (!notifyEnabled()) return;
  void (async () => {
    await notify(b.userId, "build.finished", { buildId: b.id, status: b.status, name: b.pluginName ?? "", reason: b.status === "failed" ? (b.errorCode ?? "") : "" });
    await notifyIfLowTokens(b.userId);
  })().catch(() => {});
}

/** Once a day at most: balance below the cyrus_tok_low_balance mark (only for accounts in the token economy). */
export async function notifyIfLowTokens(userId: string): Promise<void> {
  if (!notifyEnabled()) return;
  const [{ tokenSummary }, { loadTokenConfig }] = await Promise.all([import("../tokens/ledger"), import("../tokens/config")]);
  const [s, cfg] = await Promise.all([tokenSummary(userId), loadTokenConfig()]);
  if (!cfg.live || cfg.lowBalance <= 0 || s.lifetimeGranted <= 0) return;
  if (s.available < cfg.lowBalance) await notify(userId, "tokens.low", { available: String(s.available), at: Date.now() });
}

/** An install / delivery reached a final state on a server. */
export function notifyInstallResult(i: { userId: string; jobId: string; ok: boolean; name: string; server: string; restartRequired?: boolean; reason?: string | null }): void {
  if (!notifyEnabled()) return;
  void notify(i.userId, "install.result", { jobId: i.jobId, ok: i.ok, name: i.name, server: i.server, restartRequired: !!i.restartRequired, reason: i.reason ?? "" }).catch(() => {});
}

/** Something the person published, or an asset their project uses, was taken down. */
export function notifyTakedown(userId: string, t: { target: string; name: string; what: string; reason: string; counterNotice: boolean; at?: string }): void {
  if (!notifyEnabled()) return;
  void notify(userId, "takedown", { ...t, at: t.at ?? new Date().toISOString() }).catch(() => {});
}
