74	export async function cyrusLifecycleSweep(opts: { force?: boolean; mailer?: Mailer; log?: (s: string) => void } = {}): Promise<{ signals: number; autoDisabled: number; autoUpdated: number }> {
75	  const out = { signals: 0, autoDisabled: 0, autoUpdated: 0 };
76	  if (lifecycleRunning) return out;
77	  if (!opts.force && !(await getSettingBool("cyrus_lifecycle_enabled", false))) return out;
78	  lifecycleRunning = true;
79	  const log = opts.log ?? ((s: string) => console.log(`[cyrus-lifecycle] ${s}`));
80	  const mail = opts.mailer ?? (await defaultMailer());
81	  try {
82	    out.signals = await signalsFromHealth(mail, log);
83	    out.autoDisabled = await crashLoops(mail, log);
84	    out.autoUpdated = await autoUpdates(log);
85	  } finally {
86	    lifecycleRunning = false;
87	  }
88	  return out;
89	}
