94	async function signalsFromHealth(mail: Mailer, log: (s: string) => void): Promise<number> {
95	  const runs = await db.modUpdateRun.findMany({ where: { trigger: "health", startedAt: { gt: new Date(Date.now() - 3600_000) } }, orderBy: { startedAt: "asc" }, take: 200 });
96	  let n = 0;
97	  for (const run of runs) {
98	    const plan = (run.plan ?? {}) as { cyrus?: HealthCyrus[]; gameVersion?: string | null };
99	    for (const v of plan.cyrus ?? []) {
100	      const open = await cyrusDb.cyrusModSignal.findFirst({ where: { serverId: run.serverId, modId: v.modId, kind: "BROKEN", clearedAt: null } });
101	      if (v.status === "broken") {
102	        if (open && open.buildId === v.buildId) continue;
103	        if (open) await cyrusDb.cyrusModSignal.update({ where: { id: open.id }, data: { clearedAt: new Date() } });
104	        const gm = await db.gameMod.findUnique({ where: { id: v.modId }, select: { name: true, sourceId: true } });
105	        if (!gm?.sourceId) continue;
106	        // Flapping guard: at most one owner email per mod per server per day (in-app every time).
107	        const recent = await cyrusDb.cyrusModSignal.count({ where: { serverId: run.serverId, modId: v.modId, kind: "BROKEN", createdAt: { gt: new Date(Date.now() - 86_400_000) } } });
108	        await cyrusDb.cyrusModSignal.create({ data: { serverId: run.serverId, modId: v.modId, rootBuildId: gm.sourceId, buildId: v.buildId, kind: "BROKEN", evidence: v.evidence.join("\n").slice(0, 2000) || null, gameVersion: plan.gameVersion ?? null } });
109	        n++;
110	        await tellOwner(run.serverId, `${gm.name} is reporting errors`, `${v.apiMismatch ? "The game log shows it calling something this game version doesn't have, so it's out of date for this version." : "The game log shows errors naming it."} Open the Mods tab to update, roll back or switch it off.`, mail, recent === 0);
111	        log(`BROKEN ${gm.name} on ${run.serverId}`);
112	      } else if (v.status === "loaded" && open && run.startedAt > open.createdAt) {
113	        await cyrusDb.cyrusModSignal.update({ where: { id: open.id }, data: { clearedAt: new Date() } });
114	        await cyrusDb.cyrusModSignal.create({ data: { serverId: run.serverId, modId: v.modId, rootBuildId: open.rootBuildId, buildId: v.buildId, kind: "RECOVERED", gameVersion: plan.gameVersion ?? null, clearedAt: new Date() } });
115	        n++;
116	      }
117	    }
118	  }
119	  return n;
120	}
