195	async function autoUpdates(log: (s: string) => void): Promise<number> {
196	  if (!realChanges()) return 0;
197	  const rows = await db.serverMod.findMany({ where: { status: "INSTALLED", autoUpdate: "AUTO", pinned: false, mod: { source: CYRUS_SOURCE } }, include: { mod: true }, take: 200 });
198	  let n = 0;
199	  const done = new Set<string>();
200	  for (const r of rows) {
201	    if (done.has(r.serverId) || !r.mod.sourceId) continue;
202	    const server = await db.server.findUnique({ where: { id: r.serverId }, include: { osTemplate: true, gamePlan: true } });
203	    if (!server || server.status !== "RUNNING") continue;
204	    const chain = await cyrusDb.modBuild.findMany({ where: { OR: [{ id: r.mod.sourceId }, { rootBuildId: r.mod.sourceId }] }, orderBy: { createdAt: "asc" } });
205	    const head = chainHead(chain);
206	    if (!head || head.id === r.versionId) continue;
207	    if (!(await publicInstallAllowed(head, server.userId))) continue;
208	    if (await cyrusDb.cyrusModSignal.findFirst({ where: { serverId: r.serverId, modId: r.modId, kind: { in: ["BROKEN", "CRASH_LOOP"] }, buildId: head.id } })) continue; // that version already misbehaved here
209	    const family = familyFor(server) ?? "minecraft";
210	    const support = supportFor(gameOfFamily(family));
211	    if (!support) continue;
212	    const compat = checkCompat({ support, serverVersion: await serverGameVersion(server), target: head.mcVersion, builtFor: succeededVersions(chain).map((b) => b.mcVersion) });
213	    if (compat.level === "block") continue;
214	    if ((await playersOnline(r.serverId, family)) !== 0) continue; // unknown or someone online: wait
215	    if ((await db.job.count({ where: { serverId: r.serverId, status: { in: ["QUEUED", "RUNNING"] } } })) > 0) continue;
216	    const q = await enqueueModOp(r.serverId, r.modId, "update", { userId: server.userId, slug: r.mod.slug }, { targetVersionId: head.id });
217	    if (q.ok) {
218	      done.add(r.serverId);
219	      n++;
220	      log(`auto-update ${r.mod.name} on ${server.hostname} -> ${head.id}`);
221	    }
222	  }
223	  return n;
224	}
