228	export async function cyrusCompatWatchSweep(opts: { force?: boolean; dryRun?: boolean; mailer?: Mailer; log?: (s: string) => void; now?: Date } = {}): Promise<{ chains: number; raised: number; resolved: number; notified: number; emailed: number; dryRun: boolean }> {
229	  const dry = opts.dryRun ?? (await getSettingBool("cyrus_compat_watch_dry_run", true));
230	  const out = { chains: 0, raised: 0, resolved: 0, notified: 0, emailed: 0, dryRun: dry };
231	  if (watchRunning) return out;
232	  if (!opts.force && !(await getSettingBool("cyrus_compat_watch_enabled", false))) return out;
233	  watchRunning = true;
234	  const log = opts.log ?? ((s: string) => console.log(`[cyrus-compat] ${s}`));
235	  const now = opts.now ?? new Date();
236	  const mail = opts.mailer ?? (await defaultMailer());
237	  try {
238	    const [installed, published] = await Promise.all([
239	      db.gameMod.findMany({ where: { source: CYRUS_SOURCE, installs: { some: { status: { in: ["INSTALLED", "DISABLED", "UPDATING"] } } } }, select: { id: true, sourceId: true } }),
240	      cyrusDb.cyrusModPage.findMany({ where: { visibility: "PUBLIC", hiddenAt: null }, select: { rootBuildId: true } }),
241	    ]);
242	    const roots = [...new Set([...installed.map((g) => g.sourceId!).filter(Boolean), ...published.map((p) => p.rootBuildId)])].slice(0, 500);
243	    for (const root of roots) {
244	      out.chains++;
245	      const chain = await cyrusDb.modBuild.findMany({ where: { OR: [{ id: root }, { rootBuildId: root }] }, orderBy: { createdAt: "asc" } });
246	      const ok = succeededVersions(chain);
247	      const head = chainHead(chain);
248	      if (!ok.length || !head) continue;
249	      const support = supportFor("minecraft")!; // ModBuild chains are Minecraft today
250	      const gm = installed.find((g) => g.sourceId === root);
251	      const installs = gm ? await db.serverMod.findMany({ where: { modId: gm.id, status: { in: ["INSTALLED", "DISABLED", "UPDATING"] } }, select: { serverId: true, server: { select: { id: true, gameConfig: true } } } }) : [];
252	      const withVersions = await Promise.all(installs.map(async (i) => ({ serverId: i.serverId, serverVersion: await serverGameVersion(i.server) })));
253	      const newest = ok[ok.length - 1];
254	      const broken = await cyrusDb.cyrusModSignal.findMany({ where: { rootBuildId: root, kind: "BROKEN", buildId: newest.id, createdAt: { gt: new Date(now.getTime() - 7 * 86_400_000) } }, select: { serverId: true, evidence: true } });
255	      const erroring = new Set(broken.map((b) => b.serverId));
256	      const mismatch = new Set(broken.filter((b) => /NoSuchMethod|NoSuchField|NoClassDef|UnsupportedClassVersion|Unsupported API/.test(b.evidence ?? "")).map((b) => b.serverId));
257	      const facts: ChainFacts = {
258	        gameId: "minecraft",
259	        title: displayName(chain),
260	        builtFor: ok.map((b) => b.mcVersion),
261	        newestBuildId: newest.id,
262	        published: published.some((p) => p.rootBuildId === root),
263	        installs: withVersions,
264	        erroringServers: erroring.size,
265	        apiMismatchServers: mismatch.size,
266	      };
267	      const drafts = creatorAlertsFor(support, facts);
268	      const creator = chain[0].userId;
269	      const existing = await cyrusDb.cyrusCreatorAlert.findMany({ where: { rootBuildId: root } });
270	      for (const d of drafts) {
271	        const ex = existing.find((e) => e.key === d.key);
272	        const row = ex
273	          ? await cyrusDb.cyrusCreatorAlert.update({ where: { id: ex.id }, data: { lastSeenAt: now, servers: d.servers, title: d.title, body: d.body, targetVersion: d.targetVersion, buildable: d.buildable, dryRun: dry && ex.dryRun, resolvedAt: null } })
274	          : await cyrusDb.cyrusCreatorAlert.create({ data: { userId: creator, rootBuildId: root, kind: d.kind, key: d.key, gameId: facts.gameId, targetVersion: d.targetVersion, buildable: d.buildable, title: d.title, body: d.body, servers: d.servers, dryRun: dry, firstSeenAt: now, lastSeenAt: now } });
275	        if (!ex) out.raised++;
276	        const emailsThisWeek = await cyrusDb.cyrusCreatorAlert.count({ where: { userId: creator, emailedAt: { gt: new Date(now.getTime() - 7 * 86_400_000) } } });
277	        const decision = notifyDecision({ alert: row, dryRun: dry, emailsThisWeek, emailAllowed: await mayDeliverTo(creator, "cyrus_creator_alert", "email") });
278	        if (dry) {
279	          log(`DRY RUN would warn ${creator} (${facts.title}): ${d.title}`);
280	          continue;
281	        }
282	        const href = updateWithCyrusHref(head.id, d.buildable ? d.targetVersion : null);
283	        // r40: with CYRUS_NOTIFY on, the ONE Cyrus notification system carries it (bell + preference center + cyrus.my
284	        // sender; deduped per alert key). Off: the original Nxeon notification + email path below, unchanged.
285	        if (notifyEnabled()) {
286	          if (decision.inapp || decision.email) {
287	            const r = await notify(creator, "mod.outdated", { modId: root, version: d.key, name: facts.title, game: "Minecraft", builtFor: facts.builtFor.join(", "), buildId: head.id });
288	            if (r.recorded) { await cyrusDb.cyrusCreatorAlert.update({ where: { id: row.id }, data: { notifiedAt: now, ...(r.email === "sent" ? { emailedAt: now } : {}) } }); out.notified++; if (r.email === "sent") out.emailed++; }
289	          }
290	          continue;
291	        }
292	        if (decision.inapp) {
293	          await db.notification.create({ data: { userId: creator, title: d.title, body: d.body, href: d.buildable || d.kind === "ERROR_REPORTS" ? href : "/dashboard/nxlabs/cyrus" } });
294	          await cyrusDb.cyrusCreatorAlert.update({ where: { id: row.id }, data: { notifiedAt: now } });
295	          out.notified++;
296	        }
297	        if (decision.email) {
298	          const u = await db.user.findUnique({ where: { id: creator }, select: { email: true } });
299	          if (u?.email) {
300	            const sent = await mail({
301	              to: u.email, subject: d.title, userId: creator, kind: "cyrus_creator_alert",
302	              html: await emailHtml(d.title, d.body, d.buildable || d.kind === "ERROR_REPORTS" ? href : "/dashboard/nxlabs/cyrus", d.buildable ? `Update with Cyrus for ${d.targetVersion}` : "Open your mod"),
303	            }).catch(() => false);
304	            if (sent) {
305	              await cyrusDb.cyrusCreatorAlert.update({ where: { id: row.id }, data: { emailedAt: now } });
306	              out.emailed++;
307	            }
308	          }
309	        }
310	      }
311	      // Anything this chain no longer triggers is resolved (the creator shipped, errors stopped).
312	      for (const e of existing) {
313	        if (!e.resolvedAt && !drafts.some((d) => d.key === e.key)) {
314	          await cyrusDb.cyrusCreatorAlert.update({ where: { id: e.id }, data: { resolvedAt: now } });
315	          out.resolved++;
316	        }
317	      }
318	    }
319	  } finally {
320	    watchRunning = false;
321	  }
322	  log(`${out.chains} mods checked, ${out.raised} new, ${out.resolved} resolved, ${out.notified} notified, ${out.emailed} emailed${dry ? " (dry run)" : ""}`);
323	  return out;
324	}

