260	/** Build the Universe. Never throws: a project whose source fails is simply absent ("unknown"). */
261	export async function loadUniverse(ctx: LoadCtx): Promise<{ universe: Universe; errors: string[] }> {
262	  const universe: Universe = {};
263	  const errors: string[] = [];
264	  const max = ctx.maxProjects ?? 60;
265	  const inst = new Map(ctx.installed.map((p) => [p.key, p]));
266	  const v2p = new Map<string, string>();
267	  const queue: string[] = ctx.installed.filter((p) => !p.disabled).map((p) => p.key);
268	  const seen = new Set<string>();
269	  const rootMod = new Map<string, CatalogFacts>();
270	  for (const p of ctx.installed) if (p.root && p.modId && ctx.mods.get(p.modId)) rootMod.set(p.key, ctx.mods.get(p.modId)!);
271	
272	  // Catalogue rows (fallback + mirror tags), one query.
273	  let catalog: CatalogVersionRow[] = [];
274	  if (ctx.catalog) {
275	    const ids = [...rootMod.values()].map((m) => m.id);
276	    catalog = ids.length ? await ctx.catalog(ids).catch(() => []) : [];
277	  }
278	
279	  while (queue.length && seen.size < max) {
280	    const key = queue.shift()!;
281	    if (seen.has(key)) continue;
282	    seen.add(key);
283	    let info: ProjectInfo | null = null;
284	    try {
285	      if (key.startsWith("modrinth:")) info = await loadModrinth(key, ctx, inst.get(key), v2p);
286	      else if (key.startsWith("hangar:")) info = await loadHangar(key, ctx);
287	      else if (key.startsWith("thunderstore:")) info = await loadThunderstore(key, ctx, inst.get(key));
288	      else if (rootMod.has(key)) {
289	        for (const pi of await loadViaInstaller(rootMod.get(key)!, ctx)) {
290	          if (!universe[pi.key]) universe[pi.key] = pi;
291	          seen.add(pi.key);
292	        }
293	        continue;
294	      }
295	    } catch (e) {
296	      errors.push(`${key}: ${(e as Error).message}`.slice(0, 200));
297	    }
298	    // Upstream failed (or returned nothing) → the NX Labs catalogue, if it has this mod.
299	    const mod = rootMod.get(key);
300	    if ((!info || !info.versions.length) && mod) {
301	      const rows = catalog.filter((r) => r.gameModId === mod.id);
302	      if (rows.length) info = { key, name: mod.name, versions: rows.map((r) => catalogRowToCandidate(key, r, mod.source, ctx.variant, ctx.family)) };
303	    }
304	    if (!info) continue;
305	    // Tag builds the catalogue/mirror holds.
306	    if (mod) {
307	      for (const v of info.versions) {
308	        const row = catalog.find((r) => r.gameModId === mod.id && r.versionId === v.versionId);
309	        if (row) v.catalogRowId = row.id;
310	      }
311	    }
312	    if (info.key !== key) {
313	      // Canonical key differs (e.g. a slug resolved to a project id) — keep both pointing at it.
314	      universe[info.key] = { ...info };
315	    }
316	    universe[key] = { ...info, key, versions: info.versions.map((v) => ({ ...v, key })) };
317	    for (const v of info.versions) for (const d of v.deps) if (d.kind === "required" && !seen.has(d.key)) queue.push(d.key);
318	  }
319	  if (queue.length) errors.push(`stopped after ${max} projects`);
320	  return { universe, errors };
321	}
