export function configDir(pluginName: string | null): string | null {
  const n = (pluginName ?? "").replace(/[^A-Za-z0-9_-]/g, "");
  return n.length ? n : null;
}

export const cyrusPackageKey = (rootBuildId: string) => `cyrus:${rootBuildId}`;

export async function resolveCyrus(mod: CatalogFacts, ctx: InstallerCtx): Promise<Resolution | { error: string }> {
  const variant = (ctx.server.variant ?? "vanilla").toLowerCase();
  if (!CYRUS_VARIANTS.includes(variant)) return { error: `Cyrus mods are Paper plugins — this server runs ${variant}. Switch it to Paper or Purpur in Settings first.` };
  if (!mod.sourceId) return { error: "This Cyrus mod has no build history to install from." };
  const got = await (await jarSource())({ rootBuildId: mod.sourceId, targetBuildId: mod.targetVersionId ?? null, serverId: ctx.server.id });
  if ("error" in got) return got;
  const sha = createHash("sha256").update(got.bytes).digest("hex");
  if (got.build.jarSha256 && got.build.jarSha256 !== sha) return { error: "The stored plugin file doesn't match its checksum — nothing was installed. Rebuild it in Cyrus." };
  const notes: string[] = [];
  if (ctx.layout.gameVersion && got.build.mcVersion && ctx.layout.gameVersion !== got.build.mcVersion) {
    notes.push(`Built for Minecraft ${got.build.mcVersion}; your server runs ${ctx.layout.gameVersion}. Paper plugins usually carry across 1.21.x — check the console after the restart.`);
  }
  return {
    packages: [
      {
        key: cyrusPackageKey(mod.sourceId),
        name: got.name,
        version: got.packageVersion,
        versionId: got.build.id,
        file: { url: `cyrus://${got.build.id}`, filename: got.build.jarName, size: got.bytes.length, hashes: { sha256: sha } },
        placement: "plugin-jar",
        requires: [],
        incompatible: [],
        prefetched: got.bytes,
        root: true,
      },
    ],
    notes,
    // Keep a copy of the plugin's config folder (plugins/<Name>/) with the jar backup, so an
    // update or rollback can always be undone with the settings it had.
    ...(configDir(got.build.pluginName) && ctx.layout.dirs.plugins ? { alsoBackupDirs: [`${ctx.layout.dirs.plugins}/${configDir(got.build.pluginName)}`] } : {}),
  };
}

