57	/** Install (or update to) this build on one server after the customer confirmed the plan's warnings. */
58	export async function installCyrusMod(buildId: string, serverId: string, acked: string[], opts: { restart?: boolean } = {}): Promise<CyrusInstallResult> {
59	  const { user, build } = await installableBuild(buildId);
60	  if (!build) return { error: "This version can't be installed." };
61	  if (typeof serverId !== "string" || !ID.test(serverId)) return { error: "Pick a server." };
62	  const ack = Array.isArray(acked) ? acked.filter((a) => typeof a === "string").slice(0, 20) : [];
63	  const { plans } = await installPlansFor(build, user.id);
64	  const sp = plans.find((p) => p.server.id === serverId);
65	  if (!sp) return { error: "That server isn't one of your Minecraft servers." };
66	  if (sp.plan.op === "none") return { error: "That version is already on the server." };
67	  const ok = confirmPlan(sp.plan, ack);
68	  if (!ok.ok) return { error: ok.error };
69	  if (!live()) return { error: "One-click mod changes are paused right now, so nothing was installed." };
70	
71	  const r = await installBuildToServer(build, user.id, serverId, { allowPublic: build.userId !== user.id });
72	  if (!r.ok) return { error: r.error };
73	  let restarted = false;
74	  let restartNote: string | null = null;
75	  if (opts.restart && sp.plan.restart === "required") {
76	    if (r.queued) restartNote = "The install is still queued. Restart from the Mods tab once it shows as installed.";
77	    else {
78	      const p = await gamePower(serverId, "restart");
79	      restarted = p.ok;
80	      if (!p.ok) restartNote = p.error;
81	    }
82	  }
83	  if (build.userId === user.id) {
84	    await cyrusDb.modBuild.update({ where: { id: build.id }, data: { lastInstall: { serverId, serverName: r.serverName, at: new Date().toISOString(), replaced: r.replaced, backupDir: r.backupDir, restarted } } }).catch(() => {});
85	  }
86	  await db.auditLog.create({ data: { userId: user.id, action: "cyrus.install", detail: `${build.id} -> ${serverId} acked=${ack.join(",")}${build.userId !== user.id ? " (published, other creator)" : ""}`.slice(0, 900) } }).catch(() => {});
87	  revalidatePath(`/dashboard/servers/${serverId}`);
88	  return { ok: true, queued: r.queued, restarted, restartNote, replaced: r.replaced, serverName: r.serverName, modId: r.modId };
89	}
