110	export async function setCyrusModEnabled(serverId: string, modId: string, on: boolean): Promise<{ ok?: true; error?: string }> {
111	  let ctx;
112	  try {
113	    ctx = await ownedCyrusRows(serverId);
114	  } catch {
115	    return { error: "Not found." };
116	  }
117	  const { user, server } = ctx;
118	  if (typeof modId !== "string" || !ID.test(modId)) return { error: "Not found." };
119	  const row = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId } }, include: { mod: true } });
120	  if (!row || row.mod.source !== CYRUS_SOURCE) return { error: "Not found." };
121	  if (!live()) return { error: "One-click mod changes are paused right now, so nothing was changed." };
122	  if (server.status !== "RUNNING") return { error: "Start the server's VM first: mods are changed on the running server." };
123	  const family = familyFor(server) ?? row.mod.gameFamily;
