125	  if (!d.allowed) return { error: d.reason };
126	  if (on && row.status !== "DISABLED") return { error: `${row.mod.name} is already on.` };
127	  if (!on && row.status !== "INSTALLED") return { error: `${row.mod.name} is ${row.status.toLowerCase()} right now.` };
128	  const r = await enqueueModOp(serverId, modId, on ? "enable" : "disable", { userId: user.id, slug: row.mod.slug });
129	  if (!r.ok) return { error: r.error };
130	  if (on) await cyrusDb.cyrusModSignal.updateMany({ where: { serverId, modId, kind: "AUTO_DISABLED", clearedAt: null }, data: { clearedAt: new Date() } }).catch(() => {});
131	  revalidatePath(`/dashboard/servers/${serverId}`);
132	  return { ok: true };
133	}
