164	/** Update every Cyrus mod with a newer version on this server, in ONE job (config kept, each backed up). */
165	export async function updateAllCyrusMods(serverId: string): Promise<{ ok?: true; error?: string; count?: number }> {
166	  let ctx;
167	  try {
168	    ctx = await ownedCyrusRows(serverId);
169	  } catch {
170	    return { error: "Not found." };
171	  }
172	  const { user, server } = ctx;
173	  if (!live()) return { error: "One-click mod changes are paused right now, so nothing was queued." };
174	  if (server.status !== "RUNNING") return { error: "Start the server's VM first." };
175	  const rows = (await lifecycleForServer(serverId)).filter((r) => r.updateAvailable && r.latestBuildId && r.view.state !== "disabled" && !["installing", "updating", "enabling", "disabling", "removing", "failed"].includes(r.view.state));
176	  if (!rows.length) return { error: "Every Cyrus mod here is on its newest version." };
177	  // Published versions only for other creators' mods (re-checked by the engine's jar source too).
178	  const targets: { modId: string; buildId: string; slug: string }[] = [];
179	  for (const r of rows.slice(0, 25)) {
180	    const b = await cyrusDb.modBuild.findUnique({ where: { id: r.latestBuildId! } });
181	    if (!b || !(await publicInstallAllowed(b, server.userId))) continue;
182	    const gm = await db.gameMod.findUnique({ where: { id: r.modId }, select: { slug: true } });
183	    targets.push({ modId: r.modId, buildId: b.id, slug: gm?.slug ?? r.modId });
184	  }
185	  if (!targets.length) return { error: "No update can be applied right now." };
186	  const q = await withServerJobLock(serverId, async (tx) => {
187	    const inflight = await tx.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
188	    if (inflight > 0) return { ok: false as const, error: "Another operation is already running on this server. Try again when it finishes." };
189	    const cur = await tx.serverMod.findMany({ where: { serverId, modId: { in: targets.map((t) => t.modId) } }, select: { modId: true, status: true } });
190	    if (cur.some((c) => c.status !== "INSTALLED")) return { ok: false as const, error: "A mod changed while you were looking. Refresh and try again." };
191	    for (const t of targets) await tx.serverMod.update({ where: { serverId_modId: { serverId, modId: t.modId } }, data: { status: "UPDATING", error: null, targetVersionId: t.buildId } });
192	    const job = await tx.job.create({ data: { type: "GAME_MOD_SYNC", serverId, payload: { ops: targets.map((t) => ({ modId: t.modId, op: "update" })), batch: true, cyrusUpdateAll: true } }, select: { id: true } });
193	    return { ok: true as const, jobId: job.id };
194	  });
195	  if (!q.ok) return { error: q.error };
196	  await db.auditLog.createMany({ data: targets.map((t) => ({ userId: user.id, action: "gameserver.mod.update", detail: `${serverId} mod=${t.slug} version=${t.buildId} batch=${q.jobId} cyrus-update-all` })) }).catch(() => {});
197	  revalidatePath(`/dashboard/servers/${serverId}`);
198	  return { ok: true, count: targets.length };
199	}
