64	  const [sync, power] = await Promise.all([
65	    getHost().jobs.lastDone(serverId, ["GAME_MOD_SYNC"]),
66	    getHost().jobs.lastDone(serverId, ["GAME_POWER", "GAME_REINSTALL"]),
67	  ]);
68	  const p = (sync?.payload ?? {}) as { modId?: string; ops?: { modId: string }[]; result?: { restartRequired?: boolean } };
69	  if (!sync || !p.result?.restartRequired) return new Set();
70	  const restarted = !!power && power.updatedAt > sync.updatedAt && (power.payload as { action?: string } | null)?.action !== "stop";
71	  if (restarted) return new Set();
72	  return new Set([...(p.modId ? [p.modId] : []), ...(p.ops ?? []).map((o) => o.modId)]);
73	}
