83	export async function lifecycleRows(server: HostServerRow, rows: HostInstallRow[]): Promise<CyrusLifecycleRow[]> {
84	  const cy = rows.filter((r) => r.mod.source === CYRUS_SOURCE && r.mod.sourceId);
85	  if (!cy.length) return [];
86	  const family = getHost().servers.familyOf(server) ?? server.osTemplate?.family ?? "minecraft";
87	  const support = supportFor(family);
88	  const [chains, pending, signals, health, serverVersion] = await Promise.all([
89	    chainsFor([...new Set(cy.map((r) => r.mod.sourceId!))]),
90	    restartPendingFor(server.id),
91	    db.cyrusModSignal.findMany({ where: { serverId: server.id, modId: { in: cy.map((r) => r.modId) }, clearedAt: null }, orderBy: { createdAt: "desc" } }).catch(() => []),
92	    getHost().servers.lastHealthRun(server.id).catch(() => null),
93	    serverGameVersion(server),
94	  ]);
95	  const hp = (health?.plan ?? null) as HealthPlan | null;
96	  return cy.map((r) => {
97	    const chain = chains.get(r.mod.sourceId!) ?? [];
98	    const ok = succeededVersions(chain);
99	    const head = chainHead(chain);
100	    const label = (id: string | null) => {
101	      const i = ok.findIndex((b) => b.id === id);
102	      return i < 0 ? null : versionLabel({ n: i + 1, version: ok[i].version });
103	    };
104	    const installed = ok.find((b) => b.id === r.versionId) ?? null;
105	    const updateAvailable = !!r.versionId && !!head && head.id !== r.versionId;
106	    const sig = signals.filter((s) => s.modId === r.modId);
107	    const openBroken = sig.find((s) => s.kind === "BROKEN" && (!s.buildId || s.buildId === r.versionId));
108	    // A fresh log read after the last change wins over an older signal.
109	    const fresh = hp?.cyrus?.find((v) => v.modId === r.modId && (!v.buildId || v.buildId === r.versionId));
110	    const freshAfterChange = !!health && health.startedAt > r.updatedAt;
111	    const broken = fresh && freshAfterChange && fresh.status === "broken"
112	      ? { evidence: fresh.evidence[0] ?? null, apiMismatch: fresh.apiMismatch }
113	      : openBroken && !(fresh && freshAfterChange && fresh.status === "loaded")
114	        ? { evidence: openBroken.evidence, apiMismatch: /NoSuchMethod|NoSuchField|NoClassDef|UnsupportedClassVersion|Unsupported API/.test(openBroken.evidence ?? "") }
115	        : null;
116	    const auto = sig.find((s) => s.kind === "AUTO_DISABLED");
117	    const outdated = support
118	      ? outdatedReasons({ support, serverVersion, builtFor: ok.map((b) => b.mcVersion), installedTarget: installed?.mcVersion ?? null, newerBuild: updateAvailable ? label(head!.id) : null })
119	      : [];
120	    const view = deriveLifecycle({
121	      status: r.status,
122	      error: r.error,
123	      restartPending: pending.has(r.modId),
124	      broken,
125	      autoDisabled: r.status === "DISABLED" && auto ? { why: auto.evidence ?? "the game kept crashing right after it was installed." } : null,
126	      outdated,
127	      rolledBack: r.status === "INSTALLED" && !!r.error,
128	    });
129	    return {
130	      modId: r.modId,
131	      rootBuildId: r.mod.sourceId!,
132	      name: r.mod.name,
133	      view,
134	      installedLabel: label(r.versionId),
135	      latestLabel: head ? label(head.id) : null,
136	      latestBuildId: head?.id ?? null,
137	      updateAvailable,
138	      autoUpdate: r.autoUpdate === "AUTO",
139	      serverVersion,
140	    };
141	  });
142	}
