257	  if (!src || !src.jarPath) return { error: "That version can't be remixed." };
258	  const listing = await cyrusDb.cyrusModListing.findUnique({ where: { pageId: page.id }, select: { remixPolicy: true } });
259	  const srcSafety = (src.result as { safety?: { verdict?: "pass" | "warn" | "block" } } | null)?.safety?.verdict ?? null;
260	  const d = remixDecision({ viewer: user, page, policy: (listing?.remixPolicy as "OPEN" | "CLOSED" | undefined) ?? null, hasCyrus: await hasCyrus(user), scanVerdict: srcSafety });
261	  if (!d.ok) return { error: d.message };
262	  if (d.mode === "own") return { ok: true, href: `/dashboard/cyrus/${src.id}`, own: true };
263	  const me = user!;
264	  const recent = await cyrusDb.cyrusFork.count({ where: { userId: me.id, createdAt: { gte: new Date(Date.now() - 3600_000) } } });
265	  if (recent >= 10) return { error: "You've started a lot of remixes this hour. Try again later." };
266	  // D-63: a remix is a new project; in a game the account does not mod yet it needs a free game slot (plan gating)
267	  { const slot = await checkGameSlot(me, "minecraft"); if (!slot.ok) return { error: slot.error }; }
268	
269	  // 1. Re-scan BEFORE anything is copied.
270	  let bytes: Buffer;
271	  try {
272	    bytes = await readFile(src.jarPath);
273	  } catch {
274	    return { error: "That version's plugin file is missing from storage." };
275	  }
276	  // BQ-4: a remix copies the jar into the account's own storage, so a full account cannot remix (fail closed, like a build)
277	  { const st = await (await import("./cyrus/storage/service")).checkStorageWrite(me.id, bytes.length, "build"); if (!st.ok) return { error: st.error }; }
278	  const checksumOk = src.jarSha256 ? createHash("sha256").update(bytes).digest("hex") === src.jarSha256 : null;
279	  const paths = rescanPaths(((src.result as { files?: { path: string; size: number }[] } | null)?.files) ?? []);
280	  const svcId = await serviceBuildId(src.id);
281	  const files: { path: string; text: string }[] = [];
282	  try {
283	    for (const p of paths) {
284	      const r = await svcSource(svcId, p);
285	      if (!r.ok) throw new Error(`source ${r.status}`);
