290	  }
291	  const scan = rescanVerdict({ stored: srcSafety, findings: scanSourceText(files), checksumOk, files: files.length });
292	  if (scan.verdict === "block") {
293	    await audit(me.id, "cyrusmods.remix.blocked", `${page.slug} ${src.id} ${scan.findings.map((f) => f.rule).join(",")}`);
294	    return { error: `This version didn't pass the re-scan (${scan.findings[0]?.message ?? "safety check"}), so it can't be remixed. Nxeon has been told.` };
295	  }
296	
297	  // 2. Lineage: who this page itself came from.
298	  const parentRemix = await cyrusDb.cyrusRemix.findUnique({ where: { buildId: page.rootBuildId } });
299	  const originPageId = parentRemix?.originPageId ?? (page.forkOfPageId ? await legacyOrigin(page) : page.id);
300	  const depth = (parentRemix?.depth ?? (page.forkOfPageId ? 1 : 0)) + 1;
301	
302	  // 3. The copy, seeded with the prompt history.
303	  const doc = readModDoc(page.doc);
304	  const v = doc?.versions.find((x) => x.buildId === src.id);
305	  const creator = displayUser(await db.user.findUnique({ where: { id: page.userId }, select: { name: true } }));
306	  const upTo = chain.filter((b) => b.createdAt.getTime() <= src.createdAt.getTime());
307	  const notes = remixNotes({ title: page.title, creator, baseLabel: v ? versionLabel(v) : "the current version", license: page.license, slug: page.slug, steps: upTo });
308	  const id = "mb" + randomBytes(10).toString("hex");
309	  await mkdir(MODBUILD_DIR, { recursive: true, mode: 0o750 });
310	  await copyFile(src.jarPath, jarPathFor(id));
311	  const claim = await withGameSlot(me, "minecraft", (c) => c.modBuild.create({
312	    data: {
313	      id,
314	      userId: me.id,
315	      status: "succeeded",
316	      prompt: src.prompt,
317	      changeRequest: null,
318	      baseBuildId: null,
319	      rootBuildId: id,
320	      mcVersion: src.mcVersion,
321	      pluginName: src.pluginName,
322	      version: src.version,
323	      result: (src.result ?? undefined) as Prisma.InputJsonValue | undefined,
324	      attempts: 0,
325	      costUsd: 0,
326	      durationMs: 0,
327	      jarName: src.jarName,
328	      jarSize: src.jarSize,
329	      jarSha256: src.jarSha256,
330	      jarPath: jarPathFor(id),
331	      cyrus: { title: remixTitle(page.title), notes } as Prisma.InputJsonValue,
332	      finishedAt: new Date(),
333	    },
334	  }));
335	  if (!claim.ok) { await unlink(jarPathFor(id)).catch(() => undefined); return { error: claim.error }; }
336	  void (await import("./cyrus/storage/service")).noteStorageWrite(me.id, bytes.length);
337	  await cyrusDb.cyrusFork.create({ data: { buildId: id, sourceBuildId: svcId, sourcePageId: page.id, userId: me.id } });
338	  await cyrusDb.cyrusRemix.create({ data: { buildId: id, userId: me.id, parentPageId: page.id, parentBuildId: src.id, parentRootBuildId: page.rootBuildId, originPageId, depth, scan: scan as unknown as Prisma.InputJsonValue } });
339	  await syncCyrusModPage(id);
