/** GDPR erasure of the person's Cyrus data. Off unless CYRUS_GDPR_ERASE=1; the email must be typed back. */
export async function adminCyrusGdprErase(fd: FormData) {
  const admin = await guard("user.gdpr.erase");
  const t = await target(fd);
  if (!t) go(fd, "err", "No such account.");
  if (!gdprEraseEnabled()) go(fd, "err", "Erasure is switched off on this server (CYRUS_GDPR_ERASE). The plan above is a dry run.");
  if (str(fd, "typed", 200).toLowerCase() !== (t.email ?? "").toLowerCase()) go(fd, "err", "Type the account's email exactly to confirm the erasure.");
  const reason = str(fd, "reason", 200);
  if (reason.length < 3) go(fd, "err", "Give the request reference (kept in the audit log).");
  const plan = await gdprPlanFor(t.id);
  const res = await gdprErase(t.id);
  await cyrusAudit({ actorId: admin.id, action: "user.gdpr.erase", target: `user:${t.id}`, before: { delete: plan.delete, anonymise: plan.anonymise, retain: plan.retain }, after: { deleted: res.deleted, anonymised: res.anonymised, retained: res.retained, anonId: res.anonId }, note: reason });
  go(fd, "ok", `Cyrus data erased for ${t.email}: ${Object.values(res.deleted).reduce((a, b) => a + b, 0)} rows deleted, ${Object.values(res.anonymised).reduce((a, b) => a + b, 0)} anonymised; financial rows kept.`);
}
