import Link from "next/link";
import { Icon } from "@/components/nx/Icon";
import { lifecycleForServer, summarize, type ServerCyrusSummary } from "@/lib/cyrus/lifecycle/server";

/**
 * Cyrus lifecycle on the server page and the server card: a banner (server page) and a chip
 * (server list) when a Cyrus mod on the server is broken, was switched off after a crash
 * loop, failed a change, or is out of date. Renders nothing otherwise, and nothing on error:
 * a lifecycle read must never break the server page.
 */
export async function CyrusServerBanner({ serverId }: { serverId: string }) {
  let s: ServerCyrusSummary | null = null;
  try {
    const rows = await lifecycleForServer(serverId);
    s = rows.length ? summarize(rows) : null;
  } catch {
    return null;
  }
  if (!s?.headline || !s.worst || s.worst === "info") return null;
  const bad = s.worst === "bad";
  return (
    <div className={"mx-auto mb-3 flex w-full max-w-[1480px] flex-wrap items-center gap-x-3 gap-y-2 rounded-[13px] border px-3.5 py-2.5 " + (bad ? "border-rose/40 bg-rose/[0.08] text-rose" : "border-amber/45 bg-amber/[0.08] text-amber")} role={bad ? "alert" : "status"} data-testid="cyrus-server-banner">
      <Icon name={bad ? "warntriangle" : "warncircle"} size={14} tone="inherit" className="flex-none" />
      <p className="min-w-0 flex-1 text-[12.5px] font-bold">{s.headline}</p>
      <Link href={`/dashboard/servers/${serverId}?tab=mods#mod-installed`} className="text-[12px] font-semibold text-tx underline-offset-2 hover:underline">Open Mods</Link>
    </div>
  );
}

export function CyrusServerChip({ s }: { s: ServerCyrusSummary | undefined }) {
  if (!s || !s.worst || s.worst === "info") return null;
  const bad = s.worst === "bad";
  const n = s.broken + s.failed + s.autoDisabled;
  return (
    <span title={s.headline ?? undefined} data-testid="cyrus-server-chip"
      className={"inline-flex items-center gap-1 rounded-[6px] border px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide " + (bad ? "border-rose/40 bg-rose/10 text-rose" : "border-amber/45 bg-amber/[0.08] text-amber")}>
      <Icon name={bad ? "warntriangle" : "warncircle"} size={10} tone="inherit" />
      {bad ? `${n} mod${n === 1 ? "" : "s"} need attention` : `${s.outdated} outdated`}
    </span>
  );

