export function deriveLifecycle(i: LifecycleInput): LifecycleView {
  const flight = FLIGHT[i.status];
  if (flight) return { state: flight, label: STATE_LABEL[flight], tone: "info", notes: [], actions: [] };

  if (i.status === "FAILED") {
    return {
      state: "failed", label: "Failed", tone: "bad",
      notes: [i.error ?? "The last change didn't go through.", "Nothing half-installed was left behind: the engine rolls back a write that fails."],
      actions: ["retry", "remove"],
    };
  }

  const on = i.status === "INSTALLED";
  const notes: string[] = [];
  if (i.rolledBack && i.error) notes.push(`The update failed and the previous version was kept: ${i.error}`);

  if (on && i.broken) {
    return {
      state: "broken", label: "Broken", tone: "bad",
      notes: [
        i.broken.apiMismatch
          ? "The game log shows this mod calling something your game version doesn't have: it's out of date for this version."
          : "The game log shows errors naming this mod.",
        ...(i.broken.evidence ? [i.broken.evidence] : []),
        ...notes,
      ],
      actions: ["update", "rollback", "disable", "rebuild"],
    };
  }

  if (i.status === "DISABLED") {
    if (i.autoDisabled) notes.unshift(`We switched it off: ${i.autoDisabled.why} Its config and data were kept.`);
    return { state: "disabled", label: "Disabled", tone: "muted", notes, actions: ["enable", "remove"] };
  }

  if (on && i.restartPending) {
    return { state: "pending_restart", label: "Pending restart", tone: "info", notes: ["Restart the server to load this change.", ...notes], actions: ["restart", "disable"] };
  }

  if (on && i.outdated.length) {
    return {
      state: "outdated", label: "Outdated", tone: "warn",
      notes: [...i.outdated.map((o) => o.text), ...notes],
      actions: i.outdated.some((o) => o.code === "newer-build") ? ["update", "disable"] : ["rebuild", "disable"],
    };
  }

  return { state: "enabled", label: "Enabled", tone: "ok", notes, actions: ["disable", "remove"] };
}

