export async function installBuildToServer(build: ModBuild, userId: string, serverId: string, opts: { waitMs?: number; allowPublic?: boolean } = {}): Promise<InstallResult> {
  const el = await installEligibility(build, userId, serverId, opts);
  if (!el.ok) return el;
  const { own, server, facts } = el;

  const root = rootOf(build);
  const chain = await loadChain(root);
  await syncCyrusModPage(root);
  const gm = await ensureCyrusGameMod(root, chain);
  if (!gm) return { ok: false, error: "This build has no plugin file to install." };

  const existing = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId: gm.id } } });
  if (existing?.status === "DISABLED") return { ok: false, error: `${gm.name} is switched off on ${facts.name}. Switch it on in the server's Mods tab first, then install this version.` };
  if (existing && !["INSTALLED", "FAILED", "REMOVED"].includes(existing.status)) return { ok: false, error: `${gm.name} is busy on that server (${existing.status.toLowerCase()}). Try again in a moment.` };
  if (existing?.status === "INSTALLED" && existing.versionId === build.id) {
    return { ok: true, path: `${PLUGINS}/${build.jarName}`, replaced: [], backupDir: null, serverName: facts.name, queued: false, jobId: "", modId: gm.id };
  }
  const op = existing?.status === "INSTALLED" ? "update" : "install";

  // First engine install on a server an older builder install already used: adopt its jar.
  let adopted: { moved: string[]; backupDir: string | null } = { moved: [], backupDir: null };
  const touched = own && chain.some((b) => (b.lastInstall as { serverId?: string } | null)?.serverId === serverId);
  if (op === "install" && touched) {
    try {
      adopted = await adoptLegacyJars(server, chain);
    } catch (e) {
      console.error("[modbuilder] legacy adopt failed", build.id, serverId, (e as Error).message);
      return { ok: false, error: "We couldn't reach the server to check its plugins folder. Check it's online and try again." };
    }
  }

  const prevVersion = existing?.status === "INSTALLED" ? existing.version : null;
  const q = await enqueueModOp(serverId, gm.id, op, { userId, slug: gm.slug }, { targetVersionId: build.id });
  if (!q.ok) return { ok: false, error: q.error };

  // Wait (briefly) for the worker so the builder UI can report the outcome.
  const deadline = Date.now() + (opts.waitMs ?? 45_000);
  while (Date.now() < deadline) {
    await sleep(1000);
    const job = await db.job.findUnique({ where: { id: q.jobId }, select: { status: true, error: true } });
    if (!job || job.status === "QUEUED" || job.status === "RUNNING") continue;
    const sm = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId: gm.id } } });
    if (job.status === "FAILED") return { ok: false, error: sm?.error || "The install job failed. Check the server's Mods tab." };
    if (!sm || sm.status === "FAILED" || sm.versionId !== build.id) return { ok: false, error: sm?.error || "The plugin wasn't installed. Check the server's Mods tab." };
    return {
      ok: true,
      path: `${PLUGINS}/${build.jarName}`,
      replaced: [...adopted.moved, ...(prevVersion ? [`${gm.name} ${prevVersion}`] : [])],
      backupDir: adopted.backupDir,
      serverName: facts.name,
      queued: false,
      jobId: q.jobId,
      modId: gm.id,
    };
  }
  return { ok: true, path: `${PLUGINS}/${build.jarName}`, replaced: adopted.moved, backupDir: adopted.backupDir, serverName: facts.name, queued: true, jobId: q.jobId, modId: gm.id };
}

