// Unset (today): the host's database, exactly as before. Set: a separate Postgres for the Cyrus tables only; the host
// keeps its own tables (users, wallet, servers, settings) in its database and Cyrus reaches them through the seam.
// Rollback = unset it and restart. Never put this value in the browser bundle (it is a secret; only server code reads it).
type Env = Record<string, string | undefined>;

export function cyrusDatabaseUrl(env: Env = typeof process !== "undefined" ? process.env : {}): string | null {
  const v = env.CYRUS_DATABASE_URL?.trim();
  if (!v) return null;
  if (!/^postgres(ql)?:\/\//.test(v)) throw new Error("CYRUS_DATABASE_URL must be a postgres:// URL");
  if (env.DATABASE_URL && v === env.DATABASE_URL.trim()) return null; // same database: nothing is split
  return v;
}

/**
 * The ONE switch for every public/community Cyrus-mods surface (NxLabs
 * "Cyrus Mods" section, /mods/cyrus/**, /dashboard/nxlabs/cyrus/**, the
 * community layer, public source/jar downloads, fork).
 *
 * A viewer may see them when EITHER
 *   - Setting cyrus_mods_public_enabled is on (the owner's launch), OR
 *   - they are a private-preview account for "modbuilder" (lib/preview-access.ts;
 *     default: the owner's own customer account).
 * Everyone else gets a plain 404, exactly as if the route did not exist.
 *
 * Indexing: noindex + absent from the sitemap unless the PUBLIC flag is on.
 * A page is listed only when its creator made it PUBLIC and no admin hid it;
 * a creator always sees their own pages (private ones included) while they
 * pass the gate. Fails CLOSED on any DB error.
 */
import { notFound } from "next/navigation";
import { getSettingBool } from "../settings";
import { currentUser } from "../auth";
import { isPreviewUser } from "../preview-access";
export { pageVisibleTo } from "./doc";

export const CYRUS_MODS_PUBLIC_FLAG = "cyrus_mods_public_enabled";
export const CYRUS_PUBLIC_BASE = "/mods/cyrus";
export const CYRUS_PORTAL_BASE = "/dashboard/nxlabs/cyrus";

/** Pure decision (unit-tested). */
export function cyrusRouteDecision(flagOn: boolean, previewUser: boolean): "render" | "not-found" {
  return flagOn || previewUser ? "render" : "not-found";
}

export async function cyrusModsPublicEnabled(): Promise<boolean> {
  try {
    return await getSettingBool(CYRUS_MODS_PUBLIC_FLAG, false);
  } catch {
    return false;
  }
}

export type CyrusAccess = { allowed: boolean; isPublic: boolean; preview: boolean };

export async function cyrusAccessFor(user: { email?: string | null } | null | undefined): Promise<CyrusAccess> {
  const isPublic = await cyrusModsPublicEnabled();
  const preview = !isPublic && (await isPreviewUser(user, "modbuilder"));
  return { allowed: cyrusRouteDecision(isPublic, preview) === "render", isPublic, preview };
}

async function safeUser() {
  try {
    return await currentUser();
  } catch {
    return null;
  }
}

/** Route guard: 404 unless the viewer may see Cyrus mods. Returns the viewer (may be null once launched). */
export async function requireCyrusAccess() {
  const user = await safeUser();
  const access = await cyrusAccessFor(user);
  if (!access.allowed) notFound();
  return { user, access };
}

/** Metadata for gated pages: names the page only when allowed; noindex until launch. */
export async function cyrusMetadata(title: string, description?: string) {
  const user = await safeUser();
  const a = await cyrusAccessFor(user);
  if (!a.allowed) return { title: "Page not found", robots: { index: false, follow: false } };
  return { title, description, robots: a.isPublic ? undefined : { index: false, follow: false } };
}

/** Sitemap paths: only when launched (the caller adds each public page). */
export function cyrusSitemapPaths(flagOn: boolean, slugs: string[]): string[] {
  return flagOn ? [CYRUS_PUBLIC_BASE, ...slugs.map((s) => `${CYRUS_PUBLIC_BASE}/${s}`)] : [];
}

