/** server.version_changed: the mods on that server built for another version line are marked OUTDATED for their creator
 *  (CyrusCreatorAlert SERVERS_AHEAD, the same row the compat watch keeps, so the two never duplicate). */
export async function onServerVersionChanged(e: PlatformEventIn): Promise<{ outdated: number }> {
  const serverId = str(e, "serverId"), to = str(e, "to");
  if (!serverId || !to) return { outdated: 0 };
  const [{ lifecycleForServer }, { versionLine }] = await Promise.all([import("../lifecycle/server"), import("../lifecycle/compat")]);
  const rows = await lifecycleForServer(serverId).catch(() => []);
  let n = 0;
  for (const r of rows) {
    // the lifecycle view already compares the server's (new) version with the build's: "outdated" = game ahead / newer build
    if (r.view.state !== "outdated") continue;
    const root = await db.modBuild.findUnique({ where: { id: r.rootBuildId }, select: { userId: true } });
    if (!root) continue;
    const key = `SERVERS_AHEAD:minecraft:${versionLine(to)}`;
    await db.cyrusCreatorAlert.upsert({
      where: { rootBuildId_key: { rootBuildId: r.rootBuildId, key } },
      create: { userId: root.userId, rootBuildId: r.rootBuildId, kind: "SERVERS_AHEAD", key, gameId: "minecraft", targetVersion: to, buildable: false, title: `${r.name}: a server moved to Minecraft ${to}`, body: `A server running ${r.name} was updated to Minecraft ${to}. Rebuild the mod for ${versionLine(to)} so it keeps working there.`, servers: 1 },
      update: { lastSeenAt: new Date(), resolvedAt: null },
    });
    n++;
  }
  return { outdated: n };
}

